const fs = require('fs');
const path = require('path');
const dir = path.join(process.env.USERPROFILE, '.dsh', 'storages', 'session_projcache', 'sessions');
const files = fs.readdirSync(dir).filter(f => f.endsWith('.json'));
const agg = {};               // tool -> total calls
const perToolSessions = {};   // tool -> Set of session ids
const sessionRows = [];       // {sid,title,steps,toolCalls,orch,spawn,wf,sendMsg,teams}
const teams = { withMembers: 0, withMessages: 0, total: 0 };
for (const f of files) {
  let j;
  try { j = JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8')); } catch { continue; }
  const rows = j.record && j.record.rows;
  if (!rows) continue;
  const sid = f.replace('session-', '').replace('.json', '');
  const act = rows.contextActivity && rows.contextActivity.val;
  const toolCalls = { orchestrate: 0, spawn_teammate: 0, workflow: 0, send_message: 0, list_agents: 0, wait_agent: 0 };
  let totalToolCalls = 0;
  if (act && act.days) {
    for (const d of Object.values(act.days)) {
      totalToolCalls += d.toolCalls || 0;
      for (const t of Object.keys(toolCalls)) {
        if (d.tools && d.tools[t]) { toolCalls[t] += d.tools[t].n || 0; }
      }
    }
  }
  for (const [t, n] of Object.entries(toolCalls)) {
    agg[t] = (agg[t] || 0) + n;
    if (n > 0) { (perToolSessions[t] = perToolSessions[t] || new Set()).add(sid); }
  }
  const team = rows.agentTeam && rows.agentTeam.val;
  if (team) {
    teams.total++;
    if (team.members && team.members.length) teams.withMembers++;
    if (team.messages && team.messages.length) teams.withMessages++;
  }
  const stats = rows.sessionStats && rows.sessionStats.val || {};
  const title = (rows.title && rows.title.val) || '';
  const tokens = rows.tokenUsage && rows.tokenUsage.val && rows.tokenUsage.val.totals;
  sessionRows.push({
    sid: sid.slice(0, 8), title: String(title).slice(0, 30),
    steps: stats.steps || 0,
    toolCalls: totalToolCalls,
    orch: toolCalls.orchestrate, spawn: toolCalls.spawn_teammate, wf: toolCalls.workflow,
    sendMsg: toolCalls.send_message, teams: team && team.members ? team.members.length : 0,
    equiv: tokens ? Math.round((tokens.cacheReadTokens || 0) * 0.1 + (tokens.uncachedInputTokens || 0) + (tokens.outputTokens || 0) * 4) : 0,
  });
}
console.log('=== 全库工具调用总量（orchestration 相关）===');
for (const [t, n] of Object.entries(agg)) {
  console.log(`${t.padEnd(16)} 调用总数=${n}  使用过的会话数=${(perToolSessions[t] || new Set()).size}`);
}
console.log('\n=== agentTeam ===');
console.log(`含 agentTeam 数据的会话=${teams.total}, 有成员=${teams.withMembers}, 有消息=${teams.withMessages}`);
// 大会话（等效成本>5M）中的编排工具使用
const big = sessionRows.filter(r => r.equiv > 5e6).sort((a, b) => b.equiv - a.equiv);
console.log(`\n=== 等效成本>5M 的大会话共 ${big.length} 个，其中使用了 orchestrate/spawn/workflow 的：`);
for (const r of big.filter(r => r.orch + r.spawn + r.wf > 0).slice(0, 20)) {
  console.log(`  ${r.sid} equiv=${(r.equiv / 1e6).toFixed(1)}M steps=${r.steps} orch=${r.orch} spawn=${r.spawn} wf=${r.wf} sendMsg=${r.sendMsg} :: ${r.title}`);
}
const zero = big.filter(r => r.orch + r.spawn + r.wf === 0);
console.log(`\n大会话中完全没用编排/子智能体的：${zero.length}/${big.length}`);
console.log('TOP10 串行大会话:');
for (const r of zero.slice(0, 10)) {
  console.log(`  ${r.sid} equiv=${(r.equiv / 1e6).toFixed(1)}M steps=${r.steps} toolCalls=${r.toolCalls} :: ${r.title}`);
}

