    const { counters, call } = fanoutHarness();
    for (let i = 0; i < 4; i++) {
      assert.equal(call("s1", "read", { file_path: FILE }), undefined, "case1: 4th whole read passes");
    }
    const fifth = call("s1", "read", { file_path: FILE });
    assert.equal(typeof fifth, "string", "case2: 5th whole read rejected");
    assert.match(fifth, /spawn_teammate/, "case2: message suggests fanout");
    assert.equal(counters.rejectedByTool.read, 1, "counters.rejectedByTool.read == 1");
  }
  // 用例 3：拒绝后重置，再连续 4 次放行
  {
    const { call } = fanoutHarness();
    for (let i = 0; i < 5; i++) call("s1", "read", { file_path: FILE }); // 第 5 次被拒并清零
    for (let i = 0; i < 4; i++) {
      assert.equal(call("s1", "read", { file_path: FILE }), undefined, "case3: after reset 4 passes");
    }
    assert.equal(typeof call("s1", "read", { file_path: FILE }), "string", "case3: 5th again rejected");
  }
