    }
  }
  // 用例 8：threshold=8 生效
  {
    const { call } = fanoutHarness({ fanoutStreakThreshold: 8 });
    for (let i = 0; i < 7; i++) {
      assert.equal(call("s1", "read", { file_path: FILE }), undefined, "case8: 7 passes at threshold 8");
    }
    assert.equal(typeof call("s1", "read", { file_path: FILE }), "string", "case8: 8th rejected");
  }
  // 用例 10：orchestrate 清零两槽
  {
    const { call } = fanoutHarness();
    for (let i = 0; i < 4; i++) call("s1", "read", { file_path: FILE });
    call("s1", "orchestrate", { op: "full", request: "x" });
    assert.equal(call("s1", "read", { file_path: FILE }), undefined, "case10: orchestrate resets");
    for (let i = 0; i < 3; i++) call("s1", "read", { file_path: FILE });
    assert.equal(typeof call("s1", "read", { file_path: FILE }), "string", "case10: streak restarted");
  }
  // 用例 11：grep 独立触发，read 槽不受影响
  {
    const { call } = fanoutHarness();
    for (let i = 0; i < 4; i++) call("s1", "read", { file_path: FILE });
    for (let i = 0; i < 4; i++) assert.equal(call("s1", "grep", { pattern: "x", path: CWD }), undefined, "case11: grep 1-4 pass");
    assert.equal(typeof call("s1", "grep", { pattern: "x", path: CWD }), "string", "case11: 5th grep rejected");
    // read 槽仍停在 4：再 1 次整读应拒绝
    assert.equal(typeof call("s1", "read", { file_path: FILE }), "string", "case11: read slot untouched");
  }
  // 用例 13：被拒调用不清零（read×4 → 整仓 grep 被既有规则拒 → 再 1 次整读拒）
  {
    const { call } = fanoutHarness();
    for (let i = 0; i < 4; i++) call("s1", "read", { file_path: FILE });
    // 整仓 grep（cwd 即仓库根，深度不足）被 blockRootGrep 拒绝
    const rootGrep = call("s1", "grep", { pattern: "x", path: CWD });
    assert.equal(typeof rootGrep, "string", "case13: root grep rejected by existing rule");
    assert.equal(typeof call("s1", "read", { file_path: FILE }), "string", "case13: rejected grep did not reset read slot");
  }
  // 用例 13b：被拒 grep 不计数 → 4 次被拒整仓 grep 后 1 次合法模块内 grep 放行
  {
    const { call } = fanoutHarness();
    for (let i = 0; i < 4; i++) {
      assert.equal(typeof call("s1", "grep", { pattern: "x", path: CWD }), "string", "case13b: root greps rejected by existing rule");
    }
    const inner = call("s1", "grep", { pattern: "x", path: CWD + "\\dsh\\orchestrator-gate" });
    assert.equal(inner, undefined, "case13b: rejected greps did not count; legal grep passes");
  }
  // 用例 13d：被拒调用不触发 orchestrate 清零（read×3 → build 被拒 → read 第 4 次放行）
  {
    const { call } = fanoutHarness();
    for (let i = 0; i < 3; i++) call("s1", "read", { file_path: FILE });
    assert.equal(typeof call("s1", "pwsh", { command: "npm run build" }), "string", "case13d: build rejected by existing rule");
    assert.equal(call("s1", "read", { file_path: FILE }), undefined, "case13d: rejected build did not reset read slot");
  }
});

// --- fanout：有界 Map（第 501 条会话条目插入时淘汰最旧）---
withRules({ blockSerialFanout: true }, () => {
  const { out, call } = fanoutHarness();
  for (let i = 0; i < 501; i++) {
    call("s" + i, "read", { file_path: FILE });
  }
  assert.equal(out.sessionStreaks.size, 500, "bounded map: size capped at 500");
  assert.equal(out.sessionStreaks.has("s0"), false, "bounded map: oldest evicted");
  assert.equal(out.sessionStreaks.has("s500"), true, "bounded map: newest present");
});

